const roleName:Record<Role,string> = {site_admin:'مسؤول الموقع',priest:'أب الكنيسة',secretary:'أمين الخدام',sector_secretary:'أمين القطاع',servant:'خادم',member:'مخدوم'};
const roleRank:Record<Role,number> = {site_admin:5,priest:4,secretary:3,sector_secretary:2.5,servant:2,member:1};
const canManageMembers=(r:Role)=>roleRank[r]>=2;
